  24 => ['categoria_id' => 1, 'nome' => 'Demon slayer - Kimetsu No Yaiba vol. 4', 'autor' => 'Koyoharu Gotouge', 'ano_publicacao' => 2020, 'paginas' => 192, 'isbn' => '9786555120301', 'editora' => 'Panini', 'descricao' => 'Depois de ter saído da casa do oni que manipulava o tsuzumi, Tanjirou viu Zenitsu sofrer ataques de um rapaz vestindo uma máscara de javali sem revidar. Conseguirá Tanjirou impedi-lo?! E após um breve período de descanso, o garoto e seus companheiros partem rumo a uma montanha sinistra em uma missão de emergência designada pelo Esquadrão de Exterminadores de Onis, o Kisatsutai!! O que estará escondido lá...?!', 'preco' => 31.14, 'imagem' => 'demon_slayer_vol4.jpg', 'link_compra' => '../compra/demon_slayer_vol4.php'],
