  30 => ['categoria_id' => 1, 'nome' => 'Dragon Ball - 02', 'autor' => 'Akira Toriyama', 'ano_publicacao' => 2021, 'paginas' => 192, 'isbn' => 'Edição impressa — ISBN específico da tiragem', 'editora' => 'Panini', 'descricao' => 'Depois de passar tantos apuros, Goku, Bulma e seus companheiros seguem sua jornada e já conseguiram cinco das sete Esferas do Dragão!A sexta esfera já foi localizada, mas precisarão novamente da ajuda do Mestre Kame! E logo eles descobrirão também que há outros interessados na dádiva do Rei Dragão Sheng Long.', 'preco' => 24.50, 'imagem' => 'dragon_ball_2.jpg', 'link_compra' => '../compra/dragonballZ_vol02.php'],
