  34 => ['categoria_id' => 1, 'nome' => 'Naruto, Vol. 71: Eu Amo Vocês', 'autor' => 'Masashi Kishimoto', 'ano_publicacao' => 2021, 'paginas' => 192, 'isbn' => 'Edição impressa — ISBN específico da tiragem', 'editora' => 'Panini', 'descricao' => 'O Tsukuyomi Infinito é ativado e as pessoas são aprisionadas no mundo dos sonhos. Kaguya, que voltou à vida graças a Zetsu Negro, 
