  37 => ['categoria_id' => 1, 'nome' => 'Naruto Gold - Vol. 1', 'autor' => 'Masashi Kishimoto', 'ano_publicacao' => 2025, 'paginas' => 192, 'isbn' => '9788542602418', 'editora' => 'Panini', 'descricao' => 'Esta é a Vila Oculta da Folha. Naruto é o garoto mais problemático da Academia Ninja e está sempre aprontando todas!! Seu grande sonho é se tornar um shinobi 
