  45 => ['categoria_id' => 1, 'nome' => 'One Piece Vol.1', 'autor' => 'Eiichiro Oda', 'ano_publicacao' => 2024, 'paginas' => 192, 'isbn' => '9788573516975', 'editora' => 'Panini', 'descricao' => 'A tripulação pirata mais famosa dos quadrinhos finalmente joga sua âncora de novo no Brasil! Com roteiro e arte de Eiichiro Oda, 
