  46 => ['categoria_id' => 1, 'nome' => 'One Piece Vol.2', 'autor' => 'Eiichiro Oda', 'ano_publicacao' => 2021, 'paginas' => 192, 'isbn' => 'Edição impressa — ISBN específico da tiragem', 'editora' => 'Panini', 'descricao' => 'Luffy Chapéu de Palha não está mais sozinho em sua jornada, depois de admitir em sua tripulação o famoso espadachim Roronoa Zoro, 
